import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import api from '../services/api';
import PageBanner from '../components/PageBanner';
import { useAuth } from '../context/AuthContext';
import ProductCard from '../components/ProductCard';

const ProductDetails = () => {
  const { slug } = useParams();
  const { user } = useAuth();
  const [data, setData] = useState({ product: null, images: [], reviews: [], related: [] });
  const [qty, setQty] = useState(1);

  useEffect(() => {
    api.get(`/products/${slug}`).then(res => setData(res.data)).catch(() => {});
  }, [slug]);

  const product = data.product;
  if (!product) return <div className="container py-5">Loading...</div>;

  const imgUrl = product.image ? `http://localhost:8080/uploads/products/${product.image}` : 'https://images.unsplash.com/photo-1515562141207-7a88fb7ce338?w=600';

  const addToCart = async () => {
    if (!user) { window.location.href = '/login'; return; }
    try { await api.post('/cart/add', { productId: product.id, quantity: qty }); alert('Added to cart'); } catch(e){}
  };

  const addToWishlist = async () => {
    if (!user) { window.location.href = '/login'; return; }
    try { await api.post('/wishlist/add', { productId: product.id }); alert('Added to wishlist'); } catch(e){}
  };

  return (
    <>
      <PageBanner title={product.name} items={[{ label: 'Home', to: '/' }, { label: 'Shop', to: '/shop' }, { label: product.name }]} />
      <section className="section product-detail-section">
        <div className="container">
          <div className="row g-5">
            <div className="col-lg-6">
              <div className="product-gallery">
                <div className="main-image">
                  <img src={imgUrl} alt={product.name} />
                </div>
              </div>
            </div>
            <div className="col-lg-6">
              <div className="product-detail-info">
                <div className="product-meta">
                  <span className="category"><Link to={`/category/${product.category?.slug}`}>{product.category?.name}</Link></span>
                  {product.isNew && <span className="badge-new">New</span>}
                  {product.isBestSeller && <span className="badge-bestseller">Best Seller</span>}
                </div>
                <h1 className="product-title">{product.name}</h1>
                <div className="price-wrap">
                  <span className="price-new">₹ {Number(product.price).toLocaleString('en-IN', {minimumFractionDigits:2})}</span>
                  {product.oldPrice && <span className="price-old">₹ {Number(product.oldPrice).toLocaleString('en-IN', {minimumFractionDigits:2})}</span>}
                </div>
                <p className="product-short">{product.shortDescription}</p>
                <div className="product-meta-list">
                  <div><strong>SKU:</strong> {product.sku || 'N/A'}</div>
                  <div><strong>Availability:</strong> {product.stock > 0 ? <span className="text-success">In Stock ({product.stock})</span> : <span className="text-danger">Out of Stock</span>}</div>
                  {product.material && <div><strong>Material:</strong> {product.material}</div>}
                </div>
                <div className="product-actions-row">
                  <div className="qty-box">
                    <button type="button" onClick={() => qty > 1 && setQty(qty-1)}>&#8722;</button>
                    <input type="number" value={qty} readOnly />
                    <button type="button" onClick={() => setQty(Math.min(qty+1, product.stock))}>+</button>
                  </div>
                  <button className="btn-gold" onClick={addToCart} disabled={product.stock <= 0}><i className="bi bi-bag me-2"></i>Add to Cart</button>
                  <button className="btn-wishlist" onClick={addToWishlist}><i className="bi bi-heart"></i></button>
                </div>
                <div className="product-description mt-4">
                  <h5>Description</h5>
                  <p>{product.description}</p>
                </div>
              </div>
            </div>
          </div>

          {data.related && data.related.length > 0 && (
            <div className="related-products mt-5">
              <div className="section-title-wrap">
                <span className="eyebrow">You May Also Like</span>
                <h2>Related Products</h2>
                <span className="line"></span>
              </div>
              <div className="row">
                {data.related.map(p => <ProductCard key={p.id} product={p} />)}
              </div>
            </div>
          )}
        </div>
      </section>
    </>
  );
};

export default ProductDetails;
